package lec6;

public class Data_type_demo3 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		char ch = 'a';  // characters always stored in ascii value
		ch +=1; // ch = char(ch +1)
		System.out.println(ch);
		ch++; // ch = char(ch+1)
		System.out.println(ch);
		ch = (char) (ch +1);
		
	}

}
